class Node {
  constructor(val, prev = null, next = null) {
    this.val = val;
    this.prev = prev;   // the node before, or null at the head
    this.next = next;   // the node after, or null at the tail
  }
}

class Node:
    def __init__(self, val, prev=None, next=None):
        self.val = val
        self.prev = prev   # the node before, or None at the head
        self.next = next   # the node after, or None at the tail

class Node {
    int val;
    Node prev;   // the node before, or null at the head
    Node next;   // the node after, or null at the tail
    Node(int val) { this.val = val; }
}

struct Node {
    int val;
    Node* prev = nullptr;   // the node before, or nullptr at the head
    Node* next = nullptr;   // the node after, or nullptr at the tail
    Node(int v) : val(v) {}
};

function buildCircular(values) {
  if (values.length === 0) return null;
  const head = new ListNode(values[0]);
  let tail = head;
  for (let i = 1; i < values.length; i++) {
    tail.next = new ListNode(values[i]);
    tail = tail.next;
  }
  tail.next = head;   // close the ring: the tail points back to the head
  return head;
}

def build_circular(values):
    if not values:
        return None
    head = ListNode(values[0])
    tail = head
    for v in values[1:]:
        tail.next = ListNode(v)
        tail = tail.next
    tail.next = head   # close the ring: the tail points back to the head
    return head

ListNode buildCircular(int[] values) {
    if (values.length == 0) return null;
    ListNode head = new ListNode(values[0]);
    ListNode tail = head;
    for (int i = 1; i < values.length; i++) {
        tail.next = new ListNode(values[i]);
        tail = tail.next;
    }
    tail.next = head;   // close the ring: the tail points back to the head
    return head;
}

ListNode* buildCircular(const vector<int>& values) {
    if (values.empty()) return nullptr;
    ListNode* head = new ListNode(values[0]);
    ListNode* tail = head;
    for (size_t i = 1; i < values.size(); i++) {
        tail->next = new ListNode(values[i]);
        tail = tail->next;
    }
    tail->next = head;   // close the ring: the tail points back to the head
    return head;
}
